('demo-sprint', 9, 'sprint', 'ספרינט טריוויה חנוכה', 'חמש שאלות ברצף. תשובה שנבחרה ננעלת מיד, ואין חזרה לשאלות קודמות.', '{"questions":[{"text":"איך קראו למלך שגזר גזירות על היהודים בתקופת החשמונאים?","options":["אלכסנדר מוקדון","אנטיוכוס","תלמי","הורדוס"]},{"text":"איזו אות מופיעה על סביבון נפוץ בחו\"ל במקום האות פ׳?","options":["מ׳","כ׳","ש׳","ח׳"]},{"text":"איזה נר חנוכה מדליקים בלילה שבו מתחיל ראש חודש טבת?","options":["הנר הרביעי","הנר החמישי","הנר השישי","הנר השביעי"]},{"text":"כמה נרות מדליקים בסך הכול בארבעת הלילות האחרונים של חנוכה, כולל השמשים, בחנוכייה אחת?","options":["26","28","30","32"]},{"text":"באיזה מהמקורות הבאים מופיע סיפור נס פך השמן?","options":["מגילת אסתר","מסכת שבת בתלמוד","ספר בראשית","פרקי אבות"]}]}', 70, '{"method":"per_item","points":60}', 1, 'captain_only', '{"sequential":true}', 'candidate', true),
('demo-pictures', 13, 'three_pictures', 'שלוש התמונות', 'בכל שלישיית תמונות, יש פריטים שעברו שינוי בתמונה אחת לעומת השתיים האחרות.
באיזו תמונה יש הכי הרבה פרטים כאלה?', '{"ask":"בכל שלישיית תמונות, יש פריטים שעברו שינוי בתמונה אחת לעומת השתיים האחרות.\nבאיזו תמונה יש הכי הרבה פרטים כאלה?","heats":[{"title":"הסלון בערב חנוכה","pictures":[{"type":"room","wide":true,"kippah":"red","donuts":4,"window":"closed","candles":4,"shamash":true,"dreidel":"נ","cat":true,"frame":"gold","moon":true},{"type":"room","wide":true,"kippah":"blue","donuts":3,"window":"open","candles":4,"shamash":true,"dreidel":"נ","cat":false,"frame":"gold","moon":true},{"type":"room","wide":true,"kippah":"red","donuts":3,"window":"closed","candles":3,"shamash":true,"dreidel":"נ","cat":true,"frame":"gold","moon":true}]},{"title":"מטבח הסופגניות","pictures":[{"type":"kitchen","apron":"green","hat":true,"tray":6,"jam":"red","clock":9,"steam":true,"bowl":"blue"},{"type":"kitchen","apron":"red","hat":true,"tray":5,"jam":"red","clock":3,"steam":false,"bowl":"blue"},{"type":"kitchen","apron":"red","hat":false,"tray":5,"jam":"red","clock":3,"steam":true,"bowl":"yellow"}]},{"title":"רחוב בלילה","pictures":[{"type":"street","wcandles":5,"door":"blue","lamp":false,"tree":true,"dreidel":"teal","moon":"full","bike":false},{"type":"street","wcandles":5,"door":"blue","lamp":true,"tree":false,"dreidel":"teal","moon":"crescent","bike":false},{"type":"street","wcandles":6,"door":"red","lamp":true,"tree":true,"dreidel":"orange","moon":"crescent","bike":false}]}],"choices":["א","ב","ג"]}', 75, '{"method":"per_item","points":100}', 1, 'captain_only', '{}', 'candidate', true),
('demo-vault', 4, 'code_vault', 'הכספת החשמונאית', 'ארבע חידות. ארבע ספרות. קוד אחד.
פתרו את ארבע החידות וגלו את הספרות שמסתתרות מאחורי הכרטיסים.
יש לכם שלושה ניסיונות לפתוח את הכספת!', '{"ask":"ארבע חידות. ארבע ספרות. קוד אחד.","clues":[{"label":"ג","text":"כמה בנים היו לחנה בסיפור שבו בניה סירבו להיכנע לגזירות אנטיוכוס?"},{"label":"פ","text":"איזה מספר מופיע בשיר \"באנו חושך לגרש\"?"},{"label":"נ","text":"כמה אחים יש ליהודה המכבי?"},{"label":"ה","text":"איזה בית מקדש טיהרו החשמונאים?"}]}', 120, '{"method":"fixed","points":300}', 3, 'captain_only', '{"instant_feedback":true}', 'candidate', true),
('demo-memory', 35, 'sequence_memory', 'זיכרון הנרות', 'מכל קבוצה עולה נציג אחד לבמה, עם הטלפון של הקבוצה.
בכל שלב יוצג רצף של סמלי חנוכה. זכרו את הסדר!
כשהרצף ייעלם, יהיו לכם 20 שניות לשחזר אותו בטלפון.
הצלחתם? הרווחתם נקודות ועליתם לשלב הבא.
טעיתם? אתם יוצאים מהמשחק, אבל שומרים את הנקודות שצברתם.
שישה שלבים. כל שלב שווה יותר. טעות אחת — ואתם בחוץ!', '{"symbols":["candle","dreidel","sufganiya","oil_jar","menorah","coin","latke"],"stage_lengths":[3,4,5,6,7,8],"timing":{"intro_ms":3000,"show_ms":3500,"recall_ms":20000,"result_ms":6000},"stage_points":[25,35,45,55,65,75]}', 292, '{"method":"per_stage","points":25,"points_by_stage":[25,35,45,55,65,75]}', 1, 'captain_only', '{"sequential":true,"eliminate_on_fail":true,"instant_feedback":true,"memory":{"intro_ms":3000,"show_ms":3500,"recall_ms":20000,"result_ms":6000}}', 'candidate', true),
('demo-truth', 8, 'truth_or_fiction', 'האמת או ההמצאה?', 'בכל סט ארבע עובדות: שלוש אמיתיות ואחת מומצאת. מצאו את המומצאת.', '{"items":[{"facts":["בחנוכה אומרים הלל שלם בכל שמונת ימי החג.","סיפור נס פך השמן מופיע בתלמוד הבבלי, במסכת שבת.","ספרי המקבים נכללים בתנ\"ך העברי, בחלק הכתובים.","חנוכה הוא החג היחיד בלוח העברי שנמשך על פני שני חודשים: כסלו וטבת."]},{"facts":["המשחק בסביבון בחנוכה מוזכר במפורש בתלמוד.","ביידיש הסביבון נקרא \"דריידל\".","על סביבונים בארץ ישראל מופיעה האות פ׳: \"נס גדול היה פה\".","הלביבות המסורתיות של יהודי מזרח אירופה עשויות בעיקר מתפוחי אדמה."]},{"facts":["בית המקדש נחנך מחדש בכ\"ה בכסלו.","יהודה המכבי היה אחד מבניו של מתתיהו.","לפי אחד ההסברים, הכינוי \"מכבי\" בא מהמילה \"מקבת\", שפירושה פטיש.","יהודה המכבי נהרג בקרב על חומות ירושלים, ביום חנוכת המקדש."]}]}', 150, '{"method":"per_item","points":100}', 1, 'captain_only', '{}', 'candidate', true),
('demo-order', 17, 'ordering', 'הסדר הנכון', 'סדרו את האירועים לפי סדר הזמנים, מהמוקדם (למעלה) למאוחר (למטה). יש ניקוד חלקי על כל זוג שסידרתם נכון.', '{"items":[{"id":"e","label":"טיהור המקדש וחנוכת המזבח"},{"id":"b","label":"מתתיהו פותח במרד במודיעין"},{"id":"f","label":"יהודה המכבי נופל בקרב"},{"id":"a","label":"אנטיוכוס גוזר גזירות על היהודים"},{"id":"d","label":"המכבים משחררים את ירושלים"},{"id":"c","label":"מתתיהו מת, ויהודה עומד בראש המורדים"}]}', 120, '{"method":"partial","points":300}', 1, 'captain_only', '{}', 'candidate', true),
('demo-slide', 26, 'sliding_puzzle', 'פאזל ההחלקה', 'נציג אחד מכל קבוצה. מזיזים אריחים אל המשבצת הריקה עד שהתמונה מסודרת. מי שמסיים מהר יותר מקבל יותר נקודות.', '{"start":[7,3,6,2,0,8,1,4,5],"scene":{"type":"room","kippah":"blue","donuts":4,"window":"open","candles":8,"shamash":true,"dreidel":"נ","cat":true,"frame":"gold","moon":true}}', 240, '{"method":"time_linear","points":300,"minRatio":0.3}', 1, 'captain_only', '{}', 'candidate', true),
('demo-bet', 31, 'bet_puzzle', 'הימור בחידה', 'בסבב הזה מהמרים על הנקודות שלכם!
קודם בוחרים בטלפון על כמה להמר, ורק אחר כך נחשפת החידה.
זהיר: רווח קטן, בלי סיכון.
נועז: רווח גדול יותר, ואפשר גם להפסיד.
הכול או כלום: הרווח הכי גדול, וגם ההפסד.
פותרים נכון? מרוויחים. טועים? מפסידים לפי המסלול.', '{"people":["סבתא רחל","דוֹד אבי","נועה","איתי"],"items":["חנוכיית כסף","חנוכיית זכוכית לשמן","חנוכיית לגו","חנוכיית חימר"],"people_art":["grandma","uncle","girl","boy"],"items_art":["silver","glass","lego","clay"],"clues":["דוֹד אבי בחר בחנוכייה שאינה עשויה ממתכת, וגם לא מזכוכית.","נועה ואיתי לא בחרו בחנוכיית הכסף.","חנוכיית הלגו לא שייכת לדוֹד אבי.","נועה לא מדליקה בשמן, ולכן לא בחרה בחנוכיית הזכוכית."]}', 240, '{"method":"bet"}', 1, 'captain_only', '{"bet":{"baseMethod":"average_floor100","minBase":100,"defaultTrack":"safe","tracks":[{"id":"safe","label":"זהיר","winMultiplier":0.5,"lossMultiplier":0},{"id":"mid","label":"נועז","winMultiplier":1,"lossMultiplier":0.5},{"id":"all","label":"הכול או כלום","winMultiplier":2,"lossMultiplier":1}]}}', 'candidate', true),
('demo-finale', null, 'finale', 'הַשַּׁמָּשׁ', 'חידת הגמר (לדוגמה). רק שתי הקבוצות הראשונות שפותרות מקבלות נקודות.', '{"answer_type":"code","puzzle":"קחו את מספר הלילה שבו דולקים לראשונה יותר נרות (בלי השמש) ממספר בני מתתיהו. כפלו אותו במספר האותיות שעל הסביבון, והוסיפו את התאריך בכסלו שבו מדליקים את הנר הראשון. מה יצא?"}', 300, '{"method":"finals"}', 5, 'captain_only', '{"instant_feedback":true}', 'candidate', true),
